// This style of import is necessary for storybook to automatically generate the documentation for prop types and control interface
import * as React from "react";
import "./Chips.scss";
import { MpaIcon } from "../icon/MpaIcon";
import { SvgMpaIcon } from "../../assets/icons";


// Extend existing React interface that covers all HTML button attributes
export interface ChipsProps {
  /**
   * Identifying value for the chip.
   */
  id: string;
  /**
   * Determines the shape of the chip: Rectangle, Rounded.
   */
  shape?: "rectangle" | "rounded";
  /**
   * Text value to be displayed next to the chip.
   */
  label: string;
  /**
   * Determines the colour palette of the chips.
   */
  colour?:  "surface" | "primary" | "secondary" | "tertiary" | "inverse";
  /**
   * Determines type of chips outlined or filled.
   */
  type?: "outlined" | "filled";
    /**
   * custom leading icon.
   */
  leadingIcon?:  keyof typeof SvgMpaIcon | string;
  /**
   * custom trailing icon.
   */
  trailingIcon?:  keyof typeof SvgMpaIcon | string;
   /**
   * Custom onClick function that can be passed to the element for customizing behavior.
   */
   onClick?: (event?: any) => void;
}

const Chips: React.FC<ChipsProps> = ({
  id,
  label = "Label",
  shape = "rectangle",
  type = "outlined",
  trailingIcon = "X",
  leadingIcon = "UserCircle",
  colour = "surface",  
  onClick,
  ...rest
}) => {

  
  const chipClassName = [
    "mpa-chips",
    shape === "rectangle" ? "mpa-chip-rectangle" : "mpa-chip-rounded",
    `mpa-chip-${type}-${colour}`,
  ]
    .filter(Boolean)
    .join(" ");

  return (

    <div className={chipClassName}  {...rest}>
      {leadingIcon && (
        <span className="chip-leading-icon">
          <MpaIcon iconName={leadingIcon} size={24} />
        </span>
      )}
      <div className='font-mpa-chips'>{label}</div>      
      {trailingIcon && (
        <span
          className={`chip-trailing-icon ${colour}-hover`}
          onClick={onClick}
        >
          <MpaIcon iconName={trailingIcon} size={16}/>
        </span>
      )}
    </div>
  );
};

export default Chips;
